# -*- coding: utf-8 -*-
"""KADO 4.1: Claude's practical search ideas integrated into one KADO 4.0 runtime.
Single installation command, automatic backups, rollback. No auto deletion or code evolution.
"""
import ast,base64,datetime,os,shutil,subprocess,sys,tempfile,uuid,zlib
from pathlib import Path
ROOT=Path(os.environ.get('KADO_AGENTS_ROOT',r'C:\KADO\KADO-AJANLAR'))
BASE=zlib.decompress(base64.b64decode(""))
ADDON=zlib.decompress(base64.b64decode(""))
CYCLE_ANCHOR="    put_json(pstate(root)/'state.json',state)\n    return {'inventory':inv,'agents':agents,'computer':computer,'state':state}"
VOICE_ANCHOR="def voice_route(root: Path, request: str):\n    q=norm(request)"
CYCLE_NEW="""    try:
        from kado_bilgisayar_41 import cycle_hook
        if not quick: cycle_hook(root)
    except Exception as _e:
        append_log(root,'kado41_error',str(_e)[:200])
"""
VOICE_NEW="""def voice_route(root: Path, request: str):
    try:
        from kado_bilgisayar_41 import voice_find
        _reply=voice_find(root,request)
        if _reply is not None: return _reply
    except Exception:
        pass
    q=norm(request)"""

def patch(text):
    if '# KADO41_INTEGRATION_V1' in text:return text
    if text.count(CYCLE_ANCHOR)!=1 or text.count(VOICE_ANCHOR)!=1:
        raise RuntimeError('4.0 uyumluluk ankraji bulunamadi; canli dosya degistirilmedi')
    text=text.replace(CYCLE_ANCHOR,'    # KADO41_INTEGRATION_V1\n'+CYCLE_NEW+CYCLE_ANCHOR,1)
    text=text.replace(VOICE_ANCHOR,VOICE_NEW,1)
    ast.parse(text)
    return text

def install():
    if sys.version_info < (3,10):raise RuntimeError('Python 3.10+ gerekli')
    if not ROOT.is_dir():raise RuntimeError('KADO klasoru bulunamadi: '+str(ROOT))
    runtime=ROOT/'kado_otonom_40.py';addon=ROOT/'kado_bilgisayar_41.py'
    ast.parse(BASE.decode('utf-8'));ast.parse(ADDON.decode('utf-8'))
    # Existing 4.0 is preferred; install embedded 4.0 only if not yet present.
    if not runtime.exists():
        with tempfile.TemporaryDirectory(prefix='kado41_') as d:
            src=Path(d)/'KADO_40_OTONOM_TEK_ADIM.py';src.write_bytes(BASE)
            p=subprocess.run([sys.executable,str(src),'install'],cwd=str(ROOT),capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=240,env=dict(os.environ,KADO_AGENTS_ROOT=str(ROOT)))
            print(p.stdout[-3500:]);print(p.stderr[-600:])
            if p.returncode!=0 or not runtime.is_file():raise RuntimeError('4.0 kurulamadi, 4.1 uygulanmadi')
    original=runtime.read_bytes();updated=patch(original.decode('utf-8-sig')).encode('utf-8')
    backup=ROOT/'yedekler'/('kado41_'+datetime.datetime.now().strftime('%Y%m%d_%H%M%S')+'_'+uuid.uuid4().hex[:5]);backup.mkdir(parents=True)
    (backup/'kado_otonom_40.py').write_bytes(original)
    (backup/'addon_preexisted.txt').write_text('1' if addon.exists() else '0')
    if addon.exists():shutil.copy2(addon,backup/'kado_bilgisayar_41.py')
    try:
        addon.write_bytes(ADDON)
        runtime.write_bytes(updated)
        ast.parse(runtime.read_text(encoding='utf-8-sig'))
        subprocess.run([sys.executable,'-m','py_compile',str(addon),str(runtime)],check=True,capture_output=True,timeout=30)
        # No automatic second daemon. Existing KADO 4.0 daemon will load the new code on restart.
    except Exception:
        runtime.write_bytes(original)
        if (backup/'addon_preexisted.txt').read_text()=='1':shutil.copy2(backup/'kado_bilgisayar_41.py',addon)
        else:addon.unlink(missing_ok=True)
        raise
    print('KADO 4.1 KURULDU (Claude dosyasinin guvenli arama ve teshis ozellikleri)')
    print('YEDEK:',backup)
    print('KORUNDU: Mevcut sesli KADO, V3/V4, WhatsApp, ElevenLabs, Nova taslaklari')
    print('KAPALI: otomatik silme, canli kod degistirme, program yukleme, para harcama, paylasim')
    print('NOT: 4.0 daemon yeniden baslatildiginda 4.1 ek modulu cagirir.')
    print('DURUM: & "'+str(ROOT/'.venv'/'Scripts'/'python.exe')+'" "'+str(runtime)+'" status')
    print('GERI AL: & "'+str(ROOT/'.venv'/'Scripts'/'python.exe')+'" "'+str(Path(__file__).resolve())+'" rollback "'+str(backup)+'"')

def rollback(path):
    backup=Path(path).resolve()
    if backup.parent!=(ROOT/'yedekler').resolve() or not backup.name.startswith('kado41_'):
        raise RuntimeError('Gecersiz yedek yolu')
    runtime=ROOT/'kado_otonom_40.py';addon=ROOT/'kado_bilgisayar_41.py'
    if not (backup/'kado_otonom_40.py').is_file():raise RuntimeError('Yedek eksik')
    shutil.copy2(backup/'kado_otonom_40.py',runtime)
    if (backup/'addon_preexisted.txt').read_text()=='1':shutil.copy2(backup/'kado_bilgisayar_41.py',addon)
    else:addon.unlink(missing_ok=True)
    print('4.1 BAGLANTISI GERI ALINDI. 4.0 ve tum diger KADO dosyalari korundu.')

def selftest():
    import importlib.util,json
    with tempfile.TemporaryDirectory() as d:
        path=Path(d);local=path/'kado_bilgisayar_41.py';local.write_bytes(ADDON)
        spec=importlib.util.spec_from_file_location('kado_bilgisayar_41',local);mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
        src=BASE.decode('utf-8');fixed=patch(src);assert '# KADO41_INTEGRATION_V1' in fixed
        assert patch(fixed)==fixed
        ast.parse(fixed)
        assert not mod.safe_to_read(path/'missing.txt',path)
        root=path/'KADO-AJANLAR';root.mkdir()
        content=root/'kado_test.py';content.write_text('KADO41TEST bilgi kelimesi')
        private=root/'.env';private.write_text('password=abc')
        inv=root/'memory'/'kado40';inv.mkdir(parents=True)
        (inv/'inventory.json').write_text(json.dumps({'files':{str(content):[content.stat().st_size,content.stat().st_mtime],str(private):[private.stat().st_size,private.stat().st_mtime]}}))
        result=mod.update(root);assert result['indexed_total']==1,result
        assert mod.find(root,'KADO41TEST')[0]['path']==str(content)
        assert mod.find(root,'password')==[]
        assert mod.voice_find(root,'dosya ara KADO41TEST')
        assert mod.voice_find(root,'ajan sayimiz kac') is None
        assert mod.diagnostics(root)==0
        print('SELFTEST BASARILI: 10 kontrol; orijinal 4.0, 4.1 eklenti, arama, gizlilik, ses, hata raporu')

if __name__=='__main__':
    try:
        if len(sys.argv)>1 and sys.argv[1]=='selftest':selftest()
        elif len(sys.argv)>2 and sys.argv[1]=='rollback':rollback(sys.argv[2])
        elif len(sys.argv)>1 and sys.argv[1] not in ('install',):raise SystemExit('Komut: install | selftest | rollback <yedek>')
        else:selftest();install()
    except Exception as e:print('HATA:',type(e).__name__,str(e));raise SystemExit(1)
